const { accessSync } = await import('node:fs');
const pdfPath = process.env.PDF_PATH;
if (!pdfPath) { throw new Error('PDF_PATH env var not set'); }
try { accessSync(pdfPath); } catch { throw new Error('PDF file not accessible'); }
globalThis.pdfPath = pdfPath;

const { PDFParse } = (await import('pdf-parse')).default || await import('pdf-parse');
const { readFile } = await import('node:fs/promises');
const buffer = await readFile(globalThis.pdfPath);
const parser = new PDFParse({ data: buffer });
const result = await parser.getText();
await parser.destroy();
const lines = result.text.split(/\r?\n/).filter(l => l.trim().length > 0);
globalThis.heading = lines.length > 0 ? lines[0] : '';
